"""yahooquery history in batches, split into frames per symbol and error kinds per symbol.

Written from yahooquery's docs (guide/ticker/historical.md, guide/keyword_arguments.md, read 2026-10-18).
The docs don't say what history() returns for a symbol with no data; split() handles both a
DataFrame and a dict of frames and errors, and counts which shape came back.
"""
from __future__ import annotations

import time

import pandas as pd
from yahooquery import Ticker

START = "2000-01-03"
BATCH = 50


def to_yahoo(ticker: str) -> str:
    return ticker.replace(".", "-")  # BRK.B -> BRK-B, as AD-04 says


def kind(value) -> str:
    text = str(value).lower()
    return f"{type(value).__name__}:" + ("delisted" if "delisted" in text else "no data" if "no data" in text
                                         else "not found" if "not found" in text else "other")


def split(result, symbols: list[str]) -> tuple[dict, dict, str]:
    frames, errors = {}, {}
    if isinstance(result, pd.DataFrame):
        for s in result.index.get_level_values(0).unique():
            frames[s] = result.xs(s, level=0)
    elif isinstance(result, dict):
        for s, v in result.items():
            if isinstance(v, pd.DataFrame) and len(v):
                frames[s] = v
            else:
                errors[s] = kind(v)
    for s in symbols:
        if s not in frames and s not in errors:
            errors[s] = "absent"
    return frames, errors, type(result).__name__


def fetch(symbols: list[str], start: str = START) -> tuple[dict, dict, dict, float]:
    """frames, errors, shapes seen, seconds taken. One Ticker per batch of 50, asynchronous."""
    frames, errors, shapes = {}, {}, {}
    t0 = time.monotonic()
    for i in range(0, len(symbols), BATCH):
        batch = symbols[i:i + BATCH]
        try:
            result = Ticker(batch, asynchronous=True).history(start=start, interval="1d")
        except Exception as e:  # a batch that raises is counted, not fatal
            errors.update({s: f"raised:{type(e).__name__}" for s in batch})
            continue
        f, e, shape = split(result, batch)
        frames.update(f)
        errors.update(e)
        shapes[shape] = shapes.get(shape, 0) + 1
    return frames, errors, shapes, time.monotonic() - t0


def counts(values: dict) -> dict:
    out: dict[str, int] = {}
    for v in values.values():
        out[v] = out.get(v, 0) + 1
    return out

